package net.minecraft.world.item;public class ItemStack {private Item item;private int count;public ItemStack(net.minecraft.world.level.ItemLike i){this(i,1);}public ItemStack(net.minecraft.world.level.ItemLike i,int count){item=(Item)i;this.count=count;}public Item getItem(){return item;}public int getCount(){return count;}public net.minecraft.network.chat.Component getHoverName(){return net.minecraft.network.chat.Component.literal("Test item");}}